	/* (UUID(),'little-cat-tire-town-school-13','Something New','Điều mới mẻ','LITTLE_CAT_TIRE_TOWN_SCHOOL_13.mp3',NULL,'00:00:00.000','00:00:00.000','little-cat-tire-town-school',1,0,13) */
	('Tire Town School - Episode 13: Something New','Trường học Tire Town – Tập 13: Một điều mới mẻ','00:00:01.450','00:00:32.970','little-cat-tire-town-school-13'),
	('"Good morning," said Mr.Grill','"Chào buổi sáng," thầy Grill nói','00:00:01.450','00:00:32.970','little-cat-tire-town-school-13'),
	('We will do something new today','Hôm nay chúng ta sẽ làm một điều mới mẻ','00:00:35.630','00:00:38.730','little-cat-tire-town-school-13'),
	('Will we go fast, asked Zippy','Hôm nay chúng ta có được chạy thật nhanh không ạ?, Zippy hỏi','00:00:39.910','00:00:43.230','little-cat-tire-town-school-13'),
	('He looked at Eddie and grinned','Cậu nhìn Eddie rồi咧 miệng cười','00:00:43.350','00:00:45.630','little-cat-tire-town-school-13'),
	('Eddie frowned','Eddie cau mày','00:00:46.350','00:00:47.690','little-cat-tire-town-school-13'),
	('Will we tell jokes, asked Poppy','Chúng ta có kể chuyện cười không ạ?, Poppy hỏi','00:00:48.450','00:00:51.610','little-cat-tire-town-school-13'),
	('Nope, said Mr. Grill','Không đâu, thầy Grill đáp','00:00:52.610','00:00:54.990','little-cat-tire-town-school-13'),
	('Follow me','Đi theo thầy nào','00:00:55.490','00:00:57.210','little-cat-tire-town-school-13'),
	('The teacher drove down the road','Thầy giáo lái xe dọc theo con đường','00:01:09.100','00:01:11.880','little-cat-tire-town-school-13'),
	('Eddie saw lots of trees','Eddie nhìn thấy rất nhiều cây cối','00:01:13.720','00:01:16.320','little-cat-tire-town-school-13'),
	('Hmm, he thought','Hmm, cậu thầm nghĩ','00:01:17.260','00:01:19.080','little-cat-tire-town-school-13'),
	('Where are we going?','Chúng ta đang đi đâu vậy?','00:01:20.540','00:01:22.300','little-cat-tire-town-school-13'),
	('We\'re here, said Mr. Grill','Chúng ta đến nơi rồi, thầy Grill nói','00:01:29.500','00:01:32.600','little-cat-tire-town-school-13'),
	('Eddie saw a wide path','Eddie nhìn thấy một con đường rộng','00:01:33.100','00:01:35.540','little-cat-tire-town-school-13'),
	('It led into the woods','Con đường dẫn vào khu rừng','00:01:37.940','00:01:40.300','little-cat-tire-town-school-13'),
	('Mr. Grill smiled','Thầy Grill mỉm cười','00:01:41.560','00:01:43.400','little-cat-tire-town-school-13'),
	('We\'re going off-road','Chúng ta sẽ lái xe địa hình','00:01:43.920','00:01:46.300','little-cat-tire-town-school-13'),
	('Eddie smiled','Eddie mỉm cười','00:01:47.060','00:01:48.820','little-cat-tire-town-school-13'),
	('Wow, he said','Ồ, tuyệt quá!, cậu nói','00:01:49.140','00:01:51.380','little-cat-tire-town-school-13'),
	('Cool, said Jeb','Tuyệt thật!, Jeb nói','00:01:50.880','00:01:54.320','little-cat-tire-town-school-13'),
	('Fun, said Dipper','Vui quá!, Dipper nói','00:01:54.380','00:01:56.960','little-cat-tire-town-school-13'),
	('Yay, said Poppy','Hoan hô!, Poppy reo lên','00:01:57.720','00:02:00.240','little-cat-tire-town-school-13'),
	('I hope the path is bumpy','Tớ hy vọng con đường sẽ gập ghềnh','00:02:00.540','00:02:03.360','little-cat-tire-town-school-13'),
	('Zippy frowned','Zippy cau mày','00:02:04.240','00:02:05.780','little-cat-tire-town-school-13'),
	('This stinks, he cried','Chán chết đi được!, cậu kêu lên','00:02:06.360','00:02:09.260','little-cat-tire-town-school-13'),
	('I hate going off-road','Tớ ghét lái xe địa hình','00:02:09.400','00:02:12.180','little-cat-tire-town-school-13'),

